// Startup selftest & health diagnostics (M1, T004 subset).
//
// Hardware-dependent behavior (reset reason, heap/flash, NVS open) is
// target-verified, not host-mocked (AGENTS.md host/target boundary).
#include "Diagnostics.h"

#include <esp_system.h>

// Generated by scripts/build_git_sha.py on every `pio run -e esp32dev`
// (hook, platformio.ini extra_scripts); defines GIT_SHA as the 8-hex
// commit of HEAD (FR-007 boot log).
#include "git_sha.h"

namespace {

// BOARD sub-check thresholds (plan check table).
constexpr uint32_t kMinFreeHeapBytes = 30 * 1024;
constexpr uint32_t kExpectedFlashBytes = 4 * 1024 * 1024;

// Stable English names for the BOOT line (FR-007).
const char *resetReasonName(esp_reset_reason_t reason) {
  switch (reason) {
    case ESP_RST_POWERON:
      return "POWERON";
    case ESP_RST_EXT:
      return "EXT";
    case ESP_RST_SW:
      return "SW";
    case ESP_RST_PANIC:
      return "PANIC";
    case ESP_RST_INT_WDT:
      return "INT_WDT";
    case ESP_RST_TASK_WDT:
      return "TASK_WDT";
    case ESP_RST_WDT:
      return "WDT";
    case ESP_RST_DEEPSLEEP:
      return "DEEPSLEEP";
    case ESP_RST_BROWNOUT:
      return "BROWNOUT";
    case ESP_RST_SDIO:
      return "SDIO";
    case ESP_RST_UNKNOWN:
    default:
      return "UNKNOWN";
  }
}

}  // namespace

void Diagnostics::runBootSelfTest(Settings &settings, ILoadCell &loadcell,
                                  IMotion &motion) {
  Serial.print(F("BOOT fw="));
  Serial.print(kFwVersion);
  Serial.print(F(" git="));
  Serial.print(GIT_SHA);
  Serial.print(F(" reset="));
  Serial.println(resetReasonName(esp_reset_reason()));

  dispatchTracked(DeviceEvent::SelfTestStart);
  record(checkBoard());
  record(checkNvs(settings));
  record(checkHx711(loadcell));
  record(checkMotor(motion));
  dispatchTracked(DeviceEvent::SelfTestDone);

  if (model_.faultCode() != 0) {
    motion.disable();  // FR-001: every fault path disables the driver
  }
}

const CheckResult *Diagnostics::checks(size_t *count) const {
  *count = resultCount_;
  return results_;
}

CheckResult Diagnostics::checkBoard() {
  const uint32_t start = millis();
  CheckResult result;
  result.id = CheckId::Board;
  result.status = CheckStatus::Ok;
  result.errorCode = ErrorCode::None;

  const uint32_t freeHeap = ESP.getFreeHeap();
  const uint32_t flashSize = ESP.getFlashChipSize();
  result.measurement = static_cast<float>(freeHeap);

  // No 0x00xx/BOARD code block exists in FR-003: board anomalies are
  // WARN, never FAIL.
  if (freeHeap < kMinFreeHeapBytes || flashSize != kExpectedFlashBytes) {
    result.status = CheckStatus::Warn;
  }
  result.elapsedMs = millis() - start;
  return result;
}

CheckResult Diagnostics::checkNvs(Settings &settings) {
  const uint32_t start = millis();
  CheckResult result;
  result.id = CheckId::Nvs;
  result.status = CheckStatus::Ok;
  result.errorCode = ErrorCode::None;
  result.measurement = 0.0f;

  // Settings owns the Preferences handle; the raw read (no legacy
  // fallback) distinguishes first-boot defaults from a corrupt config.
  const Settings::Calibration raw = settings.readRawCalibration();
  result.measurement = raw.factor;

  if (raw.valid && raw.factor <= 0.0f) {
    // Stored but unsane: report WARN, keep the legacy silent fallback in
    // loadCalibration() behavior-preserving.
    result.status = CheckStatus::Warn;
    result.errorCode = ErrorCode::NvsCalibrationCorrupt;
  }
  result.elapsedMs = millis() - start;
  return result;
}

CheckResult Diagnostics::checkHx711(ILoadCell &loadcell) {
  const uint32_t start = millis();
  CheckResult result;
  result.id = CheckId::Hx711;
  result.status = CheckStatus::Ok;
  result.errorCode = ErrorCode::None;
  result.measurement = 0.0f;

  // FR-006/D7: wait_ready success within 1 s is the absent/connected
  // discriminator; absence is WARN-class (D3), never FAIL.
  if (!loadcell.waitReady(kHx711WaitMs)) {
    result.status = CheckStatus::NotConnected;
    result.elapsedMs = millis() - start;
    return result;
  }

  // FR-006: 500 ms variance window over two raw samples; the spread
  // decision is pinned in lib/FirmwareCore (HX711_NO_VARIATION_SPREAD,
  // test_health_eval.cpp).
  SampleWindow window;
  for (int i = 0; i < 2; ++i) {
    if (i == 1) {
      delay(kHx711VarianceMs);
    }
    int32_t raw = 0;
    if (!loadcell.rawSample(raw)) {
      result.status = CheckStatus::NotConnected;
      result.elapsedMs = millis() - start;
      return result;
    }
    window.push(static_cast<float>(raw));
  }
  const float spread = window.spread();
  result.measurement = spread;
  if (spread < HX711_NO_VARIATION_SPREAD) {
    // WARN diagnostic only; record() dispatches code 0 to the model.
    result.status = CheckStatus::Warn;
    result.errorCode = ErrorCode::Hx711NoVariation;
  }
  result.elapsedMs = millis() - start;
  return result;
}

CheckResult Diagnostics::checkMotor(IMotion &motion) {
  const uint32_t start = millis();
  CheckResult result;
  result.id = CheckId::Motor;
  result.status = CheckStatus::Ok;
  // D5: no sense wiring exists, so the EN line is never read back.
  // NO_FEEDBACK (0x0401) accompanies the result as an info note; a
  // clean OK without it would be a false positive.
  result.errorCode = ErrorCode::MotorNoFeedback;
  result.measurement = 0.0f;

  // D5: toggle EN and verify the module state follows. Restore the
  // pre-check state (boot default: disabled, FR-001 driver off).
  const bool wasEnabled = motion.isEnabled();
  motion.disable();
  const bool sawDisabled = !motion.isEnabled();
  motion.enable();
  const bool sawEnabled = motion.isEnabled();
  if (wasEnabled) {
    motion.enable();
  } else {
    motion.disable();
  }
  if (!sawDisabled || !sawEnabled) {
    // Software/driver state did not follow the EN toggle.
    result.status = CheckStatus::Fail;
  }
  result.elapsedMs = millis() - start;
  return result;
}

void Diagnostics::record(const CheckResult &result) {
  printCheck(result);
  // Only a FAIL faults the model; a WARN diagnostic (e.g.
  // NvsCalibrationCorrupt) carries its code in the log only (plan D3).
  const uint16_t code = (result.status == CheckStatus::Fail)
                            ? static_cast<uint16_t>(result.errorCode)
                            : 0;
  dispatchTracked(DeviceEvent::CheckResult, code);
  if (resultCount_ < kMaxChecks) {
    results_[resultCount_++] = result;
  }
}

void Diagnostics::dispatchTracked(DeviceEvent event, uint16_t code) {
  const DeviceState oldState = model_.state();
  model_.dispatch(event, code);
  if (model_.state() != oldState) {
    printState(oldState, model_.state(), model_.faultCode());
  }
}

void Diagnostics::printCheck(const CheckResult &result) {
  Serial.print(F("CHECK id="));
  Serial.print(checkIdName(result.id));
  Serial.print(F(" result="));
  Serial.print(checkStatusName(result.status));
  if (result.errorCode != ErrorCode::None) {
    Serial.print(F(" code=0x"));
    Serial.print(static_cast<uint16_t>(result.errorCode), HEX);
  }
  Serial.print(F(" meas="));
  Serial.print(result.measurement, 2);
  Serial.print(F(" elapsed_ms="));
  Serial.println(result.elapsedMs);
}

void Diagnostics::printState(DeviceState oldState, DeviceState newState,
                             uint16_t code) {
  Serial.print(F("STATE old="));
  Serial.print(deviceStateName(oldState));
  Serial.print(F(" new="));
  Serial.print(deviceStateName(newState));
  if (code != 0) {
    Serial.print(F(" code=0x"));
    Serial.print(code, HEX);
  }
  Serial.println();
}
